const crypto = require('crypto');

function normalizeSpainPhone(raw) {
  if (raw == null || String(raw).trim() === '') {
    return { valid: false, reason: 'empty' };
  }
  let d = String(raw).replace(/\D/g, '');
  if (d.startsWith('0034')) d = d.slice(2);
  if (d.length === 9 && /^[6789]/.test(d)) d = '34' + d;
  if (d.length === 11 && d.startsWith('34')) {
    const national = d.slice(2);
    if (/^[6789]\d{8}$/.test(national)) {
      return { valid: true, phone_digits: d };
    }
  }
  return { valid: false, reason: 'invalid_spain' };
}

const expected = $vars.PROSEGUR_PHONE_REGISTER_SECRET;
const item = $input.first().json;
const headers = item.headers || {};
const got = headers['x-prosegur-register-secret'] || headers['X-Prosegur-Register-Secret'];

if (!expected || !got || String(got) !== String(expected)) {
  return [{ json: { route: 'unauthorized' } }];
}

const body = item.body ?? item;
const phoneRaw = body.phone;
const source = String(body.source || 'unknown').slice(0, 120);
const norm = normalizeSpainPhone(phoneRaw);

if (!norm.valid) {
  return [{ json: { route: 'invalid', reason: norm.reason, source } }];
}

const phone_digits = norm.phone_digits;
const phone_hash = crypto.createHash('sha256').update(phone_digits, 'utf8').digest('hex');
const now = new Date().toISOString();

return [{
  json: {
    route: 'register',
    phone_digits,
    phone_hash,
    source,
    claimed_at: now,
    first_seen_at: now,
    first_source: source
  }
}];

const staticData = $getWorkflowStaticData('global');
if (!staticData.phones) staticData.phones = {};
if (!staticData.duplicateEvents) staticData.duplicateEvents = [];

const prep = $input.first().json;
const phone = prep.phone_digits;
const now = new Date().toISOString();

if (staticData.phones[phone]) {
  const ex = staticData.phones[phone];
  staticData.duplicateEvents.push({
    event_key: `dup_${phone}_${now}`,
    phone_digits: phone,
    received_at: now,
    source: prep.source,
    first_source: ex.first_source,
    first_seen_at: ex.first_seen_at,
    action: 'duplicate_not_processed'
  });
  return [{
    json: {
      ok: true,
      recorded: true,
      is_duplicate: true,
      phone_digits: phone,
      source: prep.source,
      first_source: ex.first_source,
      phone_hash: ex.phone_hash || prep.phone_hash,
      claimed_at: ex.claimed_at
    }
  }];
}

staticData.phones[phone] = {
  phone_digits: phone,
  phone_hash: prep.phone_hash,
  first_source: prep.source,
  first_seen_at: prep.first_seen_at,
  claimed_at: prep.claimed_at,
  meta_synced_at: ''
};

return [{
  json: {
    ok: true,
    recorded: true,
    is_duplicate: false,
    phone_digits: phone,
    phone_hash: prep.phone_hash,
    source: prep.source,
    claimed_at: prep.claimed_at,
    first_seen_at: prep.first_seen_at,
    first_source: prep.source
  }
}];

const r = $input.first().json;
const receivedAt = new Date().toISOString();
const isDup = Boolean(r.is_duplicate);
return [{
  json: {
    ...r,
    duplicate_tag: isDup ? 'duplicate' : 'new',
    is_duplicate: isDup ? 'yes' : 'no',
    received_at: receivedAt,
    first_source: r.first_source || r.source || '',
    first_seen_at: r.first_seen_at || r.claimed_at || receivedAt,
    phone_hash: r.phone_hash || ''
  }
}];
